1. Set up a Discord developer account and create a new Discord application.
2. Add a new bot to your application and copy the bot token.
3. Install Discord.js and its dependencies:

   ```
   npm install discord.js @discordjs/rest
   ```

4. Create a new JavaScript file and require the necessary modules:

   ```javascript
   const { Client, GatewayIntentBits } = require('discord.js');
   const { Routes } = require('@discordjs/rest');
   const fs = require('fs');
   ```

5. Create a new Discord client:

   ```javascript
   const client = new Client({
     intents: [GatewayIntentBits.Guilds],
   });
   ```

6. Create a command handler to handle the `ban` command:

   ```javascript
   const commands = {
     name: 'ban',
     description: 'Bans a user from the server.',
     options: [
       {
         name: 'user',
         description: 'The user to ban.',
         type: 'USER',
         required: true,
       },
       {
         name: 'reason',
         description: 'The reason for the ban.',
         type: 'STRING',
         required: false,
       },
     ],
     execute: async (interaction) => {
       // Add your ban logic here
       const user = interaction.options.getUser('user');
       const reason = interaction.options.getString('reason');
       await interaction.guild.members.ban(user, { reason });
       await interaction.reply(`User ${user.tag} has been banned with reason: ${reason}`);
     },
   };
   ```

7. Create a command array with your `ban` command:

   ```javascript
   const commandArray = [
     commands,
   ];
   ```

8. Create a file called `commands.json` with the following contents:

   ```json
   {
     "version": 1,
     "globalApplicationCommand": true,
     "commands": []
   }
   ```

9. Update the `commands.json` file with your command:

   ```json
   {
     "version": 1,
     "globalApplicationCommand": true,
     "commands": [
       {
         "name": "ban",
         "description": "Bans a user from the server."
       }
     ]
   }
   ```

10. Create a REST client to register your commands:

   ```javascript
   const rest = new REST({ version: '10' }).setToken(process.env.TOKEN);
   ```

11. Register your commands with Discord:

   ```javascript
   (async () => {
     try {
       console.log('Started refreshing application commands.');

       await rest.put(Routes.applicationCommands(process.env.CLIENT_ID), { body: commandArray });

       console.log('Successfully reloaded application commands.');
     } catch (error) {
       console.error(error);
     }
   })();
   ```

12. Finally, start your Discord client and listen for the `interactionCreate` event:

   ```javascript
   client.on('ready', () => {
     console.log(`Logged in as ${client.user.tag}!`);
   });

   client.on('interactionCreate', async (interaction) => {
     if (!interaction.isCommand()) return;

     const { commandName } = interaction;

     if (commandName === 'ban') {
       await commands.execute(interaction);
     }
   });

   client.login(process.env.TOKEN);
   ```

