#include <iostream>
#include <string>
#include <pugixml.hpp>

std::string convertMarkdownToHtml(std::string& markdown) {
    pugi::xml_document doc;
    pugi::xml_parse_result result = doc.load_buffer(markdown.data(), markdown.length());

    if (!result) {
        std::cerr << "Error parsing Markdown: " << result.description() << std::endl;
        return ""; // return empty string on error
    }

    // Convert the parsed XML tree to HTML
    std::string html;
    pugi::xml_node root = doc.document_element();

    // Add the HTML doctype and basic structure
