                html += "    <h6>";
            } else if (tag == "ul") {
                html += "    <ul>";
            } else if (tag == "ol") {
                html += "    <ol>";
            } else if (tag == "li") {
                html += "      <li>";
            } else if (tag == "strong") {
                html += "    <strong>";
            } else if (tag == "em") {
                html += "    <em>";
            } else if (tag == "a") {
                std::string href = node.child("a").attribute("href").value();
                html += "    <a href=\"" + href + "\">";
            }
            for (pugi::xml_node child : node.children()) {
                if (child.type() == pugi::node_text) {
                    html += child.value();
                } else if (child.type() == pugi::node_element) {
                    convertElement(child, html);
                }
            }
            if (tag == "p" || tag == "ul" || tag == "ol") {
                html += "    </" + tag + ">\n";
            } else if (tag == "li") {
                html += "      </li>\n";
            } else {
                html += "    </" + tag + ">\n";
            }
        }
    }

    html += "  </body>\n";
    html += "</html>\n";

    return html;
}

void convertElement(pugi::xml_node node, std::string& html) {
