    } else if (tag == "h6") {
        html += "    <h6>";
    } else if (tag == "ul") {
        html += "    <ul>";
    } else if (tag == "ol") {
        html += "    <ol>";
    } else if (tag == "li") {
        html += "      <li>";
    } else if (tag == "strong") {
        html += "    <strong>";
    } else if (tag == "em") {
        html += "    <em>";
    } else if (tag == "a") {
        std::string href = node.child("a").attribute("href").value();
        html += "    <a href=\"" + href + "\">";
    }

    for (pugi::xml_node child : node.children()) {
