Here's some sample code to get you started using SDL library:

```c
#include <SDL2/SDL.h>
#include <SDL2/SDL_image.h>
#include <stdio.h>
#include <stdlib.h>

#define SCREEN_WIDTH 800
#define SCREEN_HEIGHT 600
#define FOOD_WIDTH 20
#define FOOD_HEIGHT 20
#define SNAKE_WIDTH 20
#define SNAKE_HEIGHT 20

enum Direction {
    UP,
    DOWN,
    LEFT,
    RIGHT,
};

struct Snake {
    int x, y;
    enum Direction dir;
    int len;
    int *body;
};

struct Food {
    int x, y;
};

// Function prototypes
void initSDL();
void closeSDL();
void drawBoard(SDL_Renderer *renderer);
void drawSnake(SDL_Renderer *renderer, struct Snake *snake);
void drawFood(SDL_Renderer *renderer, struct Food *food);
bool isCollision(struct Snake *snake, struct Food *food);
bool moveSnake(struct Snake *snake);
void updateSnake(struct Snake *snake);
void freeSnake(struct Snake *snake);

int main(int argc, char *argv[]) {
    SDL_Window *window;
    SDL_Renderer *renderer;
    SDL_Event event;
    bool quit = false;
    int score = 0;

    struct Snake snake = {400, 300, RIGHT, 1, NULL};
    struct Food food = {rand() % (SCREEN_WIDTH / FOOD_WIDTH) * FOOD_WIDTH,
                         rand() % (SCREEN_HEIGHT / FOOD_HEIGHT) * FOOD_HEIGHT};

    initSDL();
    SDL_SetRenderDrawColor(renderer, 0, 0, 0, SDL_ALPHA_OPAQUE);
    SDL_RenderClear(renderer);

    while (!quit) {
        while (SDL_PollEvent(&event)) {
            if (event.type == SDL_QUIT) {
                quit = true;
            } else if (event.type == SDL_KEYDOWN) {
                switch (event.key.keysym.sym) {
                    case SDLK_UP:
                        snake.dir = UP;
                        break;
                    case SDLK_DOWN:
                        snake.dir = DOWN;
                        break;
                    case SDLK_LEFT:
                        snake.dir = LEFT;
                        break;
                    case SDLK_RIGHT:
                        snake.dir = RIGHT;
                        break;
                }
            }
        }

        if (moveSnake(&snake)) {
            updateSnake(&snake);
            drawBoard(renderer);
            drawSnake(renderer, &snake);
            drawFood(renderer, &food);
            score++;
        }

        if (isCollision(&snake, &food)) {
            food.x = rand() % (SCREEN_WIDTH / FOOD_WIDTH) * FOOD_WIDTH;
            food.y = rand() % (SCREEN_HEIGHT / FOOD_HEIGHT) * FOOD_HEIGHT;
            snake.len++;
            snake.body = (int *)realloc(snake.body, snake.len * sizeof(int));
            snake.body[snake.len - 1] = snake.x;
            snake.body[snake.len - 2] = snake.y;
        }

        SDL_RenderPresent(renderer);
        SDL_Delay(10);
    }

    closeSDL();
    printf("Score: %d\n", score);
    return 0;
}

void initSDL() {
    if (SDL_Init(SDL_INIT_VIDEO) < 0) {
        printf("SDL could not initialize! SDL_Error: %s\n", SDL_GetError());
        exit(EXIT_FAILURE);
    }

    if (IMG_Init(IMG_INIT_PNG) < IMG_INIT_PNG) {
        printf("SDL_image could not initialize! SDL_image_Error: %s\n", IMG_GetError());
        SDL_Quit();
        exit(EXIT_FAILURE);
    }

    window = SDL_CreateWindow("Snake Game", SDL_WINDOWPOS_CENTERED, SDL_WINDOWPOS_CENTERED,
                               SCREEN_WIDTH, SCREEN_HEIGHT, SDL_WINDOW_SHOWN);
    if (window == NULL) {
        printf("Window could not be created! SDL_Error: %s\n", SDL_GetError());
        IMG_Quit();
        SDL_Quit();
        exit(EXIT_FAILURE);
    }

    renderer = SDL_CreateRenderer(window, -1, SDL_RENDERER_ACCELERATED |
                                   SDL_RENDERER_PRESENTVSYNC);
    if (renderer == NULL) {
        printf("Renderer could not be created! SDL_Error: %s\n", SDL_GetError());
        SDL_DestroyWindow(window);
        IMG_Quit();
        SDL_Quit();
        exit(EXIT_FAILURE);
    }
}

void closeSDL() {
    SDL_DestroyRenderer(renderer);
    SDL_DestroyWindow(window);
    IMG_Quit();
    SDL_Quit();
}

void drawBoard(SDL_Renderer *renderer) {
    SDL_Rect board = {0, 0, SCREEN_WIDTH, SCREEN_HEIGHT};
    SDL_SetRenderDrawColor(renderer, 255, 255, 255, SDL_ALPHA_OPAQUE);
    SDL_RenderFillRect(renderer, &board);
}

void drawSnake(SDL_Renderer *renderer, struct Snake *snake) {
    SDL_Rect snakePart = {snake->x, snake->y, SNAKE_WIDTH, SNAKE_HEIGHT};
    SDL_SetTextureColorMod(renderer, 255, 0, 0);
    SDL_RenderCopy(renderer, NULL, NULL, &snakePart);

    for (int I = 0; I < snake->len - 1; i++) {
        snakePart.x = snake->body[i];
        snakePart.y = snake->body[i + 1];
        SDL_RenderCopy(renderer, NULL, NULL, &snakePart);
    }
}

void drawFood(SDL_Renderer *renderer, struct Food *food) {
    SDL_Rect foodRect = {food->x, food->y, FOOD_WIDTH, FOOD_HEIGHT};
    SDL_SetTextureColorMod(renderer, 255, 255, 0);
    SDL_RenderCopy(renderer, NULL, NULL, &foodRect);
}

bool isCollision(struct Snake *snake, struct Food *food) {
    int snakeX = snake->x + (SNAKE_WIDTH / 2);
    int snakeY = snake->y + (SNAKE_HEIGHT / 2);
    int foodX = food->x + (FOOD_WIDTH / 2);
    int foodY = food->y + (FOOD_HEIGHT / 2);

    if (snakeX == foodX && snakeY == foodY) {
        return true;
    }

    return false;
}

bool moveSnake(struct Snake *snake) {
    int newX, newY;

    switch (snake->dir) {
        case UP:
            newY = snake->y - SNAKE_HEIGHT;
            break;
        case DOWN:
            newY = snake->y + SNAKE_HEIGHT;
            break;
        case LEFT:
            newX = snake->x - SNAKE_WIDTH;
            break;
        case RIGHT:
            newX = snake->x + SNAKE_WIDTH;
            break;
    }

    if (newX < 0 || newX >= SCREEN_WIDTH - SNAKE_WIDTH) {
        return false;
    }

    if (newY < 0 || newY >= SCREEN_HEIGHT - SNAKE_HEIGHT) {
        return false;
    }

    snake->x = newX;
    snake->y = newY;

    return true;
}

void updateSnake(struct Snake *snake) {
    int tailX, tailY;

    for (int I = snake->len - 2; I >= 0; i--) {
        tailX = snake->body[i];
        tailY = snake->body[i + 1];
        snake->body[i] = tailX;
        snake->body[i + 1] = tailY;
    }

    snake->body[snake->len - 1] = snake->x;
    snake->body[snake->len - 2] = snake->y;
}

void freeSnake(struct Snake *snake) {
    free(snake->body);
}
```

This is just a basic starting point, and there are many improvements and additional features you can add to make the game more polished and engaging. Good luck!

Here's a JavaScript function that takes an array of 5 numbers and checks if any of them is a valid prime number:

```javascript
function checkPrime(arr) {
  for (let I = 0; I < arr.length; i++) {
    const num = arr[i];
    if (isPrime(num)) {
      console.log(num);
      break; // exit the loop once a prime number is found
    }
  }
}

function isPrime(num) {
  if (num < 2) {
    return false;
  }
  for (let I = 2; I <= Math.sqrt(num); i++) {
    if (num % I === 0) {
      return false;
    }
  }
  return true;
}

// Example usage:
const arr = [17, 23, 42, 31, 11];
checkPrime(arr); // Output: 17, 23, 31, 11 (only prime numbers are printed)
```

The `checkPrime` function takes an array `arr` as input, loops through each number in the array, and calls the `isPrime` function to check if the number is prime. If a prime number is found, it prints the number to the console and breaks out of the loop.

The `isPrime` function checks if a given number `num` is prime using the standard method of dividing the number by all integers from 2 up to the square root of the number. If any number divides `num` evenly, it's not prime and the function returns `false`. If no such divisor is found, the number is prime and the function returns `true`. 

Note that this implementation only checks up to the square root of the number to optimize the algorithm, since any factors larger than the square root would have a corresponding factor smaller than the square root. Also, the function assumes that the input array contains only numeric values. If non-numeric values are present, the function will throw an error.

